<template><view class="mg-mres"><view class="card"><text class="title">{{snapshot?.mode==='PK'?'PK 结算':'合作结算'}}</text><text v-if="snapshot?.mode==='COOP'" class="team">团队闪避 {{snapshot.teamContribution}} / {{snapshot.teamTarget}} · {{snapshot.teamCompleted?'挑战成功':'继续加油'}}</text><view class="list"><view v-for="p in snapshot?.players||[]" :key="p.playerId"><strong>#{{p.rank}} {{p.displayName}}</strong><text>得分 {{p.score}} · 闪避 {{p.successes||0}} · 完成 {{p.overallCompletionPercent}}%</text></view></view><button @click="done">返回首页</button></view></view></template><script lang="ts">import{getMoleMultiplayerClient,clearMoleMultiplayer}from'../../runtime/multiplayer-runtime';import{returnToCaller}from'../../../game-platform/runtime/navigation';import type{RoomSnapshot}from'../../../game-platform/multiplayer/types';export default{name:'MoleMultiResult',data(){return{snapshot:null as RoomSnapshot|null,unsub:null as(()=>void)|null}},onLoad(){const c=getMoleMultiplayerClient();this.snapshot=c?.store.getSnapshot()??null;this.unsub=c?.store.subscribe(s=>this.snapshot=s)??null},onUnload(){this.unsub?.()},methods:{done(){clearMoleMultiplayer();returnToCaller()}}}</script><style scoped>.mg-mres{display:flex;align-items:center;justify-content:center;width:100vw;height:100vh;background:linear-gradient(145deg,#e6f5d6,#fff0bc);font-family:"Microsoft YaHei",sans-serif;color:#41562a}.card{width:min(650px,86vw);padding:22px;border:4px solid #79a23d;border-radius:22px;background:#fff}.title,.team{display:block;text-align:center}.title{font-size:38px;font-weight:900;color:#70932e}.team{margin:6px}.list view{display:flex;justify-content:space-between;padding:10px;border-bottom:1px solid #dfe9cf}.list text{font-size:12px}.card button{display:block;width:240px;height:44px;margin:14px auto 0;border:0;border-radius:999px;background:#75a63d;color:#fff;font-weight:900}</style>
